<?php
namespace App\Console\Commands;
use App\Models\MediaAsset; use App\Services\LegacyMediaReader; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\File; use Illuminate\Support\Facades\Storage;
class LegacyMigrateMediaCommand extends Command {protected $signature='legacy:migrate-media {--ids=} {--dry-run} {--apply} {--out=docs/generated/media-migration-sample}';public function handle(LegacyMediaReader $reader):int{$ids=array_filter(array_map('intval',explode(',',(string)$this->option('ids'))));if(!$ids||count($ids)>10||($this->option('dry-run')&&$this->option('apply'))){$this->error('Use 1-10 explicit IDs and one mode.');return self::FAILURE;}$r=['mode'=>$this->option('apply')?'apply':'dry-run','items'=>[]];foreach(DB::connection('legacy_wp')->table('posts')->whereIn('ID',$ids)->where('post_type','attachment')->get() as $a){try{$x=$reader->inspect($a->guid);$item=['legacy_attachment_id'=>$a->ID,'source_present'=>true,...$x];if($this->option('apply')){$name='media/originals/'.$x['checksum'].'.'.pathinfo($x['source'],PATHINFO_EXTENSION);$asset=MediaAsset::firstOrCreate(['checksum'=>$x['checksum']],['legacy_attachment_id'=>$a->ID,'original_path'=>$name,'mime'=>$x['mime'],'width'=>$x['width'],'height'=>$x['height'],'bytes'=>$x['bytes'],'alt_text'=>$a->post_excerpt]);$disk=Storage::disk(config('legacy-media.disk'));if(!$disk->exists($name))$disk->put($name,file_get_contents($x['source']));$item['destination']=$asset->original_path;$item['variants']=$this->variants($asset,$disk,$name);}$r['items'][]=$item;}catch(\Throwable $e){$r['items'][]=['legacy_attachment_id'=>$a->ID,'source_present'=>false,'anomaly'=>'missing_or_invalid_source'];}}$b=base_path($this->option('out'));File::put($b.'.json',json_encode($r,JSON_PRETTY_PRINT));File::put($b.'.md','# Media migration pilot\n\n```json\n'.json_encode($r,JSON_PRETTY_PRINT).'\n```\n');return self::SUCCESS;}private function variants($asset,$disk,$name):array{if(!str_starts_with($asset->mime,'image/')||!function_exists('imagewebp'))return [];$src=imagecreatefromstring($disk->get($name));if(!$src)return [];$out=[];foreach(config('legacy-media.variants') as $v){$w=min($v['width'],$asset->width);$h=(int)round($asset->height*$w/$asset->width);$path='media/variants/'.$asset->checksum.'-'.$w.'.webp';if(!$disk->exists($path)){$im=imagecreatetruecolor($w,$h);imagecopyresampled($im,$src,0,0,0,0,$w,$h,$asset->width,$asset->height);ob_start();imagewebp($im,null,82);$disk->put($path,ob_get_clean());imagedestroy($im);} $asset->variants()->firstOrCreate(['format'=>'webp','width'=>$w],['height'=>$h,'path'=>$path]);$out[]=$path;}imagedestroy($src);return $out;}}
